{
  "title": "Phishing: Spoofed DocuSign Notification",
  "id": "example-001",
  "status": "stable",
  "description": "Detects phishing emails mimicking DocuSign notifications with credential harvesting links.",
  "author": "SOC Team",
  "logsource": {
    "product": "email_gateway",
    "service": "smtp"
  },
  "detection": {
    "selection": {
      "sender": "*@docusign-verify.xyz",
      "subject|contains": "Action Required",
      "subject|contains": "Review and Sign",
      "url|contains": "docusign-verify.xyz"
    },
    "condition": "selection"
  },
  "fields": ["sender", "subject", "url", "recipient"],
  "level": "high"
}
